-- ============================================================
-- DATASET MASSIVO DI TEST - MARIA DB / NIS2
-- Dati sintetici, plausibili e coerenti tra le tabelle.
-- ATTENZIONE: lo script svuota le tabelle prima del caricamento.
-- audit_log non viene popolata direttamente: se i trigger sono attivi,
-- gli INSERT genereranno automaticamente le righe di audit.
-- Alcuni NULL sono intenzionali quando semanticamente corretti.
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE notifiche_incidente;
TRUNCATE TABLE incidenti_asset;
TRUNCATE TABLE incidenti;
TRUNCATE TABLE compliance_azienda;
TRUNCATE TABLE controlli_compliance;
TRUNCATE TABLE vulnerabilita_asset;
TRUNCATE TABLE responsabilita;
TRUNCATE TABLE dipendenze_asset_servizi;
TRUNCATE TABLE asset;
TRUNCATE TABLE contratti;
TRUNCATE TABLE servizi;
TRUNCATE TABLE persone;
TRUNCATE TABLE fornitori;
TRUNCATE TABLE livelli_criticita;
TRUNCATE TABLE ruoli;
TRUNCATE TABLE tipi_asset;
TRUNCATE TABLE aziende;
TRUNCATE TABLE audit_log;

SET FOREIGN_KEY_CHECKS = 1;
START TRANSACTION;








































































































































































COMMIT;

SELECT 'aziende' AS tabella, COUNT(*) AS righe FROM aziende
UNION ALL SELECT 'fornitori', COUNT(*) FROM fornitori
UNION ALL SELECT 'persone', COUNT(*) FROM persone
UNION ALL SELECT 'servizi', COUNT(*) FROM servizi
UNION ALL SELECT 'contratti', COUNT(*) FROM contratti
UNION ALL SELECT 'asset', COUNT(*) FROM asset
UNION ALL SELECT 'dipendenze_asset_servizi', COUNT(*) FROM dipendenze_asset_servizi
UNION ALL SELECT 'responsabilita', COUNT(*) FROM responsabilita
UNION ALL SELECT 'vulnerabilita_asset', COUNT(*) FROM vulnerabilita_asset
UNION ALL SELECT 'controlli_compliance', COUNT(*) FROM controlli_compliance
UNION ALL SELECT 'compliance_azienda', COUNT(*) FROM compliance_azienda
UNION ALL SELECT 'incidenti', COUNT(*) FROM incidenti
UNION ALL SELECT 'incidenti_asset', COUNT(*) FROM incidenti_asset
UNION ALL SELECT 'notifiche_incidente', COUNT(*) FROM notifiche_incidente
UNION ALL SELECT 'audit_log', COUNT(*) FROM audit_log
;
