INSERT INTO controlli_compliance (id_controllo, riferimento_normativo, categoria, nome_controllo, descrizione) VALUES
  (1, 'NIS2', 'Governance', 'Gestione del rischio cyber', 'Definire un processo periodico per identificare, valutare e trattare i rischi di sicurezza informatica.'),
  (2, 'NIS2', 'Governance', 'Ruoli e responsabilita di sicurezza', 'Formalizzare ruoli, responsabilita e deleghe relative alla sicurezza delle informazioni.'),
  (3, 'NIS2', 'Asset Management', 'Inventario degli asset', 'Mantenere un inventario aggiornato degli asset hardware, software, dati e servizi critici.'),
  (4, 'NIS2', 'Access Control', 'Gestione degli account', 'Gestire il ciclo di vita degli account e rimuovere tempestivamente quelli non piu necessari.'),
  (5, 'NIS2', 'Access Control', 'Accessi privilegiati', 'Limitare, autorizzare e monitorare l uso degli account con privilegi elevati.'),
  (6, 'NIS2', 'Access Control', 'Autenticazione forte', 'Adottare meccanismi di autenticazione forte per gli accessi sensibili e remoti.'),
  (7, 'NIS2', 'Network Security', 'Segmentazione di rete', 'Separare logicamente le reti e limitare i flussi tra segmenti in base alle necessita operative.'),
  (8, 'NIS2', 'Network Security', 'Protezione perimetrale', 'Configurare e monitorare i controlli di sicurezza sui punti di interconnessione con reti esterne.'),
  (9, 'NIS2', 'Vulnerability Management', 'Scansione delle vulnerabilita', 'Eseguire scansioni periodiche e registrare le vulnerabilita rilevate sugli asset.'),
  (10, 'NIS2', 'Vulnerability Management', 'Gestione delle patch', 'Definire tempi di applicazione delle patch in funzione della criticita e dell esposizione.'),
  (11, 'NIS2', 'Incident Management', 'Gestione degli incidenti', 'Definire procedure per rilevare, classificare, contenere e risolvere gli incidenti.'),
  (12, 'NIS2', 'Incident Management', 'Escalation degli incidenti', 'Stabilire criteri di escalation tecnica e manageriale in base alla severita dell evento.'),
  (13, 'NIS2', 'Incident Management', 'Notifica degli incidenti', 'Definire responsabilita, tempi e modalita per le notifiche verso le autorita competenti.'),
  (14, 'NIS2', 'Business Continuity', 'Piano di continuita operativa', 'Mantenere un piano aggiornato per assicurare la continuita dei servizi essenziali.'),
  (15, 'NIS2', 'Business Continuity', 'Disaster recovery', 'Predisporre procedure di ripristino per sistemi e servizi in caso di indisponibilita grave.'),
  (16, 'NIS2', 'Backup', 'Politica di backup', 'Definire frequenza, conservazione, protezione e responsabilita relative ai backup.'),
  (17, 'NIS2', 'Backup', 'Test di ripristino', 'Eseguire periodicamente prove di ripristino per verificare l efficacia delle copie di sicurezza.'),
  (18, 'NIS2', 'Logging', 'Raccolta dei log', 'Raccogliere e conservare log utili alla sicurezza e alla ricostruzione degli eventi.'),
  (19, 'NIS2', 'Logging', 'Monitoraggio degli eventi', 'Analizzare eventi e segnalazioni per individuare comportamenti anomali o incidenti.'),
  (20, 'NIS2', 'Supply Chain', 'Valutazione dei fornitori', 'Valutare i rischi di sicurezza associati a fornitori e servizi esterni prima dell affidamento.'),
  (21, 'NIS2', 'Supply Chain', 'Clausole di sicurezza contrattuali', 'Inserire requisiti di sicurezza e livelli di servizio nei contratti con i fornitori.'),
  (22, 'NIS2', 'Cryptography', 'Cifratura dei dati', 'Proteggere con cifratura i dati sensibili durante la trasmissione e, quando necessario, a riposo.'),
  (23, 'NIS2', 'Data Protection', 'Classificazione delle informazioni', 'Classificare le informazioni in base a sensibilita, criticita e requisiti di protezione.'),
  (24, 'NIS2', 'Awareness', 'Formazione del personale', 'Erogare formazione periodica sulla sicurezza informatica e sui principali rischi operativi.'),
  (25, 'NIS2', 'Physical Security', 'Accesso ai locali tecnici', 'Limitare e registrare l accesso fisico ai locali che ospitano sistemi critici.'),
  (26, 'NIS2', 'Change Management', 'Gestione delle modifiche', 'Autorizzare, testare e documentare le modifiche che possono influire sulla sicurezza.'),
  (27, 'NIS2', 'Configuration', 'Configurazioni sicure', 'Definire baseline di configurazione sicura per sistemi, apparati di rete e applicazioni.'),
  (28, 'NIS2', 'Third Party', 'Monitoraggio dei servizi esterni', 'Verificare periodicamente prestazioni, sicurezza e continuita dei servizi affidati a terzi.'),
  (29, 'NIS2', 'Privacy', 'Gestione dei dati personali', 'Applicare misure organizzative e tecniche adeguate ai trattamenti di dati personali.'),
  (30, 'NIS2', 'Testing', 'Test di sicurezza', 'Pianificare verifiche tecniche periodiche, incluse prove di vulnerabilita e test di sicurezza.'),
