INSERT INTO compliance_azienda (id_compliance, id_azienda, id_controllo, stato_attuale, data_verifica, gap_rilevato, azione_correttiva, note) VALUES
  (1, 1, 1, 'CONFORME', '2025-01-19', 'Nessun gap significativo rilevato durante la verifica documentale e tecnica.', 'Mantenere il controllo attivo e ripetere la verifica secondo la periodicita prevista.', 'Valutazione positiva sul controllo ''Gestione del rischio cyber'' con evidenze archiviate nel fascicolo di compliance.'),
  (2, 1, 2, 'PARZIALE', '2025-01-30', 'Il controllo ''Ruoli e responsabilita di sicurezza'' risulta implementato solo in parte; alcune evidenze o procedure non sono ancora complete.', 'Completare le attivita mancanti, formalizzare le evidenze e pianificare una nuova verifica entro 90 giorni.', 'Priorita media assegnata al piano di adeguamento relativo a NIS2.'),
