INSERT INTO incidenti (id_incidente, id_azienda, titolo, descrizione, severita, stato, data_apertura, data_chiusura, notifica_autorita_richiesta, causa, soluzione, note) VALUES
  (1, 1, 'Accesso anomalo a sistema critico', 'Rilevato un accesso non autorizzato a un sistema critico con attivita anomala sull account amministrativo.', 'CRITICA', 'APERTO', '2024-01-20 09:00:00', NULL, 1, 'Credenziali privilegiate compromesse a seguito di phishing mirato.', 'Account disabilitato, credenziali ruotate e sessioni attive invalidate; analisi forense in corso.', 'Evento registrato dal SOC interno; ticket INC-00001. Asset principale coinvolto: AZ001.'),
  (2, 1, 'Malfunzionamento firewall perimetrale', 'Il firewall perimetrale ha manifestato instabilita e perdita intermittente di connettivita.', 'ALTA', 'IN_GESTIONE', '2024-02-18 10:13:00', NULL, 0, 'Errore software successivo a un aggiornamento firmware.', 'Eseguito rollback del firmware e attivata configurazione ridondata.', 'Evento registrato dal SOC interno; ticket INC-00002. Asset principale coinvolto: AZ001.'),
  (3, 1, 'Rilevazione malware su postazione', 'Il sistema EDR ha rilevato codice malevolo su una postazione di lavoro aziendale.', 'MEDIA', 'RISOLTO', '2024-03-18 11:26:00', '2024-03-19 14:26:00', 0, 'Esecuzione di allegato malevolo ricevuto tramite posta elettronica.', 'Postazione isolata, file rimosso e scansione completa eseguita con esito negativo.', 'Evento registrato dal SOC interno; ticket INC-00003. Asset principale coinvolto: AZ001.'),
  (4, 1, 'Errore procedura di backup', 'Una finestra di backup non e stata completata correttamente e alcune copie non risultavano aggiornate.', 'MEDIA', 'CHIUSO', '2024-04-16 12:39:00', '2024-04-17 22:39:00', 0, 'Spazio disponibile insufficiente sul repository di destinazione.', 'Liberato spazio, rieseguito il backup e introdotta una soglia di allarme preventiva.', 'Evento registrato dal SOC interno; ticket INC-00004. Asset principale coinvolto: AZ001.'),
  (5, 1, 'Indisponibilita database di produzione', 'Il database di produzione ha smesso di rispondere causando indisponibilita di piu servizi dipendenti.', 'CRITICA', 'APERTO', '2024-05-15 13:52:00', NULL, 1, 'Saturazione delle risorse a seguito di una query applicativa anomala.', 'Terminata la query anomala, aumentate le risorse e introdotto monitoraggio specifico sulle query lunghe.', 'Evento registrato dal SOC interno; ticket INC-00005. Asset principale coinvolto: AZ001.'),
  (6, 1, 'Guasto apparato di rete', 'Un apparato di rete ha cessato di funzionare causando degrado della connettivita locale.', 'ALTA', 'IN_GESTIONE', '2024-06-13 14:05:00', NULL, 1, 'Guasto hardware a un componente di alimentazione.', 'Sostituito il componente guasto e verificata la ridondanza del collegamento.', 'Evento registrato dal SOC interno; ticket INC-00006. Asset principale coinvolto: AZ001.'),
  (7, 1, 'Tentativo di esfiltrazione dati', 'Sono stati rilevati trasferimenti anomali di dati verso un servizio esterno non autorizzato.', 'CRITICA', 'RISOLTO', '2024-07-12 15:18:00', '2024-07-14 22:18:00', 1, 'Compromissione di un account utente tramite credenziali riutilizzate.', 'Bloccato il traffico, revocato l account e avviata analisi dei dati potenzialmente coinvolti.', 'Evento registrato dal SOC interno; ticket INC-00007. Asset principale coinvolto: AZ001.'),
  (8, 1, 'Degrado servizio cloud', 'Il servizio cloud ha registrato latenze elevate e timeout intermittenti per parte degli utenti.', 'MEDIA', 'CHIUSO', '2024-08-10 16:31:00', '2024-08-13 06:31:00', 0, 'Riduzione delle prestazioni presso il provider esterno.', 'Attivato il canale di escalation con il provider e applicate misure temporanee di mitigazione.', 'Evento registrato dal SOC interno; ticket INC-00008. Asset principale coinvolto: AZ001.'),
  (9, 1, 'Errore certificato applicativo', 'Un applicazione ha presentato errori di connessione sicura a causa della scadenza del certificato.', 'BASSA', 'CHIUSO', '2024-09-08 17:44:00', '2024-09-11 14:44:00', 0, 'Mancato rinnovo automatico di un certificato TLS.', 'Rinnovato il certificato e introdotto un controllo automatico sulle scadenze.', 'Evento registrato dal SOC interno; ticket INC-00009. Asset principale coinvolto: AZ001.'),
  (10, 1, 'Interruzione del servizio ERP', 'Indisponibilita del servizio ERP con impatto sulle attivita amministrative e operative.', 'ALTA', 'IN_GESTIONE', '2024-10-07 08:57:00', NULL, 0, 'Errore di configurazione introdotto durante una modifica pianificata.', 'Ripristinata la configurazione precedente e avviata revisione della procedura di change management.', 'Evento registrato dal SOC interno; ticket INC-00010. Asset principale coinvolto: AZ001.'),
